"""Independent small BF16 stage evaluator; no MLX/Torch/framework imports."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import struct
from pathlib import Path
from typing import cast

Matrix = list[list[float]]


def object_map(value: object) -> dict[str, object]:
    if not isinstance(value, dict) or not all(isinstance(key, str) for key in value):
        raise ValueError("Expected JSON object with string keys")
    return cast(dict[str, object], value)


def matrix(value: object, rows: int, columns: int) -> Matrix:
    if not isinstance(value, list) or len(value) != rows:
        raise ValueError("Tiny fixture row count differs")
    result: Matrix = []
    for row in cast(list[object], value):
        if not isinstance(row, list) or len(row) != columns:
            raise ValueError("Tiny fixture column count differs")
        converted: list[float] = []
        for item in cast(list[object], row):
            if type(item) not in (int, float):
                raise ValueError("Expected ordinary finite JSON number")
            number = float(cast(int | float, item))
            if not math.isfinite(number):
                raise ValueError("Nonfinite fixture value")
            converted.append(number)
        result.append(converted)
    return result


def f32(value: float) -> float:
    return cast(float, struct.unpack("<f", struct.pack("<f", value))[0])


def bf16(value: float) -> float:
    """IEEE nearest, ties-even BF16 from finite F32, independent of frameworks."""
    bits = cast(int, struct.unpack("<I", struct.pack("<f", value))[0])
    rounded = ((bits + 0x7FFF + ((bits >> 16) & 1)) >> 16) << 16
    return cast(float, struct.unpack("<f", struct.pack("<I", rounded))[0])


def linear(value: list[float], weights: Matrix, *, reduced: bool) -> list[float]:
    operand = [bf16(item) for item in value] if reduced else value
    return [
        (bf16 if reduced else f32)(
            math.fsum(
                x * (bf16(w) if reduced else w)
                for x, w in zip(operand, row, strict=True)
            )
        )
        for row in weights
    ]


def difference(actual: list[float], expected: list[float]) -> dict[str, object]:
    absolute = [abs(a - e) for a, e in zip(actual, expected, strict=True)]
    return {
        "max_abs": max(absolute),
        "unequal_indices": [
            index
            for index, (a, e) in enumerate(zip(actual, expected, strict=True))
            if a != e
        ],
        "original_tolerance_failures": [
            index
            for index, (a, e) in enumerate(zip(actual, expected, strict=True))
            if abs(a - e) > 2e-6 + 2e-5 * abs(e)
        ],
    }


def evaluate(payload: dict[str, object]) -> dict[str, object]:
    arm = payload["arm"]
    if arm not in ("all-down", "all-gate-up", "all-mlp"):
        raise ValueError("Unknown fixed arm")
    value = matrix(payload["input"], 1, 16)[0]
    if any(abs(item) > 2 or item * 8 != round(item * 8) for item in value):
        raise ValueError("Input differs from declared eighth-integer tiny fixture")
    weights_object = object_map(payload["weights"])
    weights = {
        "gate": matrix(weights_object["gate"], 32, 16),
        "up": matrix(weights_object["up"], 32, 16),
        "down": matrix(weights_object["down"], 16, 32),
    }
    for weight in weights.values():
        if any(abs(item) > 2 or bf16(item) != item for row in weight for item in row):
            raise ValueError("Source weights must be finite, bounded, exact BF16")
    stages: dict[str, dict[str, list[float]]] = {}
    for backend in ("mlx", "torch"):
        observed = object_map(payload[backend])
        stages[backend] = {
            "gate": matrix(observed["gate"], 1, 32)[0],
            "up": matrix(observed["up"], 1, 32)[0],
            "activation": matrix(observed["activation"], 1, 32)[0],
            "down": matrix(observed["down"], 1, 16)[0],
        }
    gate = linear(value, weights["gate"], reduced=arm != "all-down")
    up = linear(value, weights["up"], reduced=arm != "all-down")
    # Double-exp SiLU rounded to F32, then explicit F32 product. This bounds a
    # numerical reference; it does not prove a transcendental implementation.
    activation = [
        f32(f32(g / (1 + math.exp(-g))) * u) for g, u in zip(gate, up, strict=True)
    ]
    reference = {
        "gate": gate,
        "up": up,
        "activation": activation,
        "down": linear(activation, weights["down"], reduced=arm != "all-gate-up"),
    }
    comparisons = {
        backend: {
            name: difference(observed[name], reference[name])
            for name in ("gate", "up", "activation", "down")
        }
        for backend, observed in stages.items()
    }
    cross_backend = {
        name: difference(stages["mlx"][name], stages["torch"][name])
        for name in ("gate", "up", "activation", "down")
    }
    product_mismatches = {
        backend: [
            name for name in ("gate", "up") if stages[backend][name] != reference[name]
        ]
        for backend in stages
    }
    first_divergent = next(
        (
            name
            for name in ("gate", "up", "activation", "down")
            if stages["mlx"][name] != stages["torch"][name]
        ),
        None,
    )
    sparse_exact = sum(item != 0 for item in value) <= 1
    return {
        "arm": arm,
        "reference": reference,
        "comparisons": comparisons,
        "cross_backend": cross_backend,
        "first_cross_backend_unequal_stage": first_divergent,
        "bf16_product_mismatch_stages": product_mismatches,
        "sparse_product_exact_fp32_before_rounding": sparse_exact,
        "verdict": (
            "BF16 product rounding discrepancy localized"
            if sparse_exact and any(product_mismatches.values())
            else "No BF16 product rounding discrepancy; later-stage cause unknown"
        ),
        "limits": (
            "Sparse one-term BF16 operands yield an exactly representable F32 product "
            "before explicit BF16 ties-even rounding. Dense math.fsum contractions "
            "are numerical references, not a formal proof. Activation uses double "
            "math.exp; later-stage unequal bits alone do not establish incorrectness."
        ),
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    input_path = cast(Path, args.input)
    output_path = cast(Path, args.output)
    input_bytes = input_path.read_bytes()
    decoded: object = json.loads(input_bytes)
    payload = object_map(decoded)
    if "diagnostic" in payload:
        payload = object_map(payload["diagnostic"])
    source = Path(__file__).read_bytes()
    result = evaluate(payload)
    result.update(
        {
            "input_sha256": hashlib.sha256(input_bytes).hexdigest(),
            "evaluator_sha256": hashlib.sha256(source).hexdigest(),
            "evaluator_text": source.decode(),
            "recorded_runtime": payload.get("runtime"),
        }
    )
    with output_path.open("x") as output:
        output.write(json.dumps(result, indent=2, allow_nan=False) + "\n")
    print(
        json.dumps(
            {
                key: result[key]
                for key in (
                    "input_sha256",
                    "evaluator_sha256",
                    "first_cross_backend_unequal_stage",
                    "bf16_product_mismatch_stages",
                    "verdict",
                )
            }
        )
    )


if __name__ == "__main__":
    main()
